import * as THREE from 'three/webgpu';
import { texture, uv, mix, color, float, vec4 } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'journal-card-3-label';

  const colors = Object.assign(
    {
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
      surface: '#0b0b10',
    },
    config.colors || {}
  );

  const pos = config.scenePosition || { x: 3.2, y: 1, z: 0.06 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };

  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const originalY = pos.y;
  const originalScale = { x: scl.x, y: scl.y, z: scl.z };

  // Atlas region (used for aspect ratio)
  const atlas = config.atlas || {
    index: 0,
    sourceRect: { x: 0, y: 0, w: 512, h: 320 },
  };
  const srcW = atlas.sourceRect.w;
  const srcH = atlas.sourceRect.h;
  const aspect = srcW / srcH;

  const planeW = 1.4;
  const planeH = planeW / aspect;

  // Card backdrop plane
  const planeGeo = new THREE.PlaneGeometry(planeW, planeH);
  const material = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
    opacity: 0.92,
  });

  if (config.imageUrl) {
    const tex = ctx.textureLoader(config.imageUrl);
    if (tex) {
      // TSL shader: sample texture with atlas rect transform
      const sx = float(srcW / 512);
      const sy = float(srcH / 320);
      const ox = float(atlas.sourceRect.x / 512);
      const oy = float(atlas.sourceRect.y / 320);
      const transformedUv = uv().mul(vec2(sx, sy)).add(vec2(ox, oy));
      material.colorNode = texture(tex, transformedUv);
    } else {
      material.colorNode = mix(
        color(colors.surface),
        color(colors.ink),
        float(0.6)
      );
    }
  } else {
    material.colorNode = mix(
      color(colors.surface),
      color(colors.ink),
      float(0.6)
    );
  }

  const plane = new THREE.Mesh(planeGeo, material);
  plane.renderOrder = 0;
  group.add(plane);

  // Accent edge frame — appears on focus / hover
  const edgeGeo = new THREE.EdgesGeometry(planeGeo);
  const edgeMat = new THREE.LineBasicMaterial({
    color: new THREE.Color(colors.accent),
    transparent: true,
    opacity: 0,
  });
  const edges = new THREE.LineSegments(edgeGeo, edgeMat);
  edges.position.z = 0.0015;
  group.add(edges);

  // Text label rendered via MSDF atlas
  const textContent = config.textContent || {
    text: 'Journal 3',
    size: 39,
    weight: 400,
    role: 'headline',
    family: 'Lora',
  };

  let textMesh = null;
  if (ctx.fontAtlas) {
    textMesh = ctx.fontAtlas(textContent.text, {
      fontFamily: textContent.family || 'Lora',
      fontWeight: textContent.weight || 400,
      fontSize: textContent.size || 39,
      color: colors.paper,
      align: 'left',
      anchorX: 'left',
      anchorY: 'middle',
    });
  }

  if (textMesh) {
    textMesh.position.set(-planeW * 0.42, -planeH * 0.32, 0.003);
    group.add(textMesh);
  }

  // Interaction state
  const timelines = [];
  const state = { hovered: false, focused: false };

  const updateEdgeOpacity = () => {
    const target = state.focused ? 1.0 : state.hovered ? 0.85 : 0.0;
    gsap.to(edgeMat, {
      opacity: target,
      duration: 0.3,
      ease: 'power2.out',
      overwrite: true,
    });
  };

  const handlers = {
    onHover: (entered) => {
      state.hovered = !!entered;
      // rise-in preset adapted: subtle 0.15 scene units
      gsap.killTweensOf(group.position);
      gsap.to(group.position, {
        y: state.hovered ? originalY + 0.15 : originalY,
        duration: state.hovered ? 0.7 : 0.5,
        ease: state.hovered ? 'power3.out' : 'power2.out',
        overwrite: true,
      });
      updateEdgeOpacity();
    },
    onClick: () => {
      // press-down preset
      gsap.killTweensOf(group.scale);
      const tl = gsap.timeline();
      tl.to(group.scale, {
        x: originalScale.x * 0.97,
        y: originalScale.y * 0.97,
        z: originalScale.z * 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      });
      tl.to(group.scale, {
        x: originalScale.x,
        y: originalScale.y,
        z: originalScale.z,
        duration: 0.18,
        ease: 'power2.out',
      });
      timelines.push(tl);

      if (ctx.emit) {
        ctx.emit('hub-journal.select', {
          id: 'journal-card-3',
          label: textContent.text,
          source: 'journal-card-3-label',
        });
      }
    },
    onFocus: (focused) => {
      state.focused = !!focused;
      updateEdgeOpacity();
    },
  };

  group.userData.handlers = handlers;
  group.userData.config = config;
  group.userData.position0 = { x: pos.x, y: pos.y, z: pos.z };
  group.userData.scale0 = { x: scl.x, y: scl.y, z: scl.z };
  group.userData.colors = colors;

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(edgeMat);
    planeGeo.dispose();
    edgeGeo.dispose();
    if (material.dispose) material.dispose();
    edgeMat.dispose();
    if (textMesh) {
      if (textMesh.geometry && textMesh.geometry.dispose) {
        textMesh.geometry.dispose();
      }
      if (textMesh.material) {
        if (Array.isArray(textMesh.material)) {
          textMesh.material.forEach((m) => m && m.dispose && m.dispose());
        } else if (textMesh.material.dispose) {
          textMesh.material.dispose();
        }
      }
    }
  };

  return group;
}
